const DEFAULT_SCHOOL = '燕京理工学院';

function searchSchools(keyword, limit) {
  var kw = (keyword || '').trim();
  var cap = limit || 30;
  if (!kw) return [];
  var res = [], loose = [];
  for (var i = 0; i < SCHOOLS.length; i++) {
    var s = SCHOOLS[i];
    var item = { name: s[0], province: s[1], city: s[2], level: s[3], type: s[4] };
    if (s[0].indexOf(kw) > -1) { res.push(item); if (res.length >= cap) return res; continue; }
    // 简称模糊匹配：关键词的每个字按顺序出现在校名中（如“深职”→“深圳职业技术大学”）
    var p = 0, ok = kw.length >= 2;
    if (ok) { for (var j = 0; j < kw.length; j++) { p = s[0].indexOf(kw[j], p); if (p < 0) { ok = false; break; } p++; } }
    if (ok) loose.push(item);
  }
  for (var k = 0; k < loose.length && res.length < cap; k++) res.push(loose[k]);
  return res;
}

module.exports = { SCHOOLS: SCHOOLS, DEFAULT_SCHOOL: DEFAULT_SCHOOL, searchSchools: searchSchools };
